@prefix prov: <http://www.w3.org/ns/prov#> .
@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/metadata-record-001> ;
            sh:resultMessage "A CDIFcomplete dataset should describe its variables (schema:variableMeasured)." ;
            sh:resultPath schema1:variableMeasured ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "A CDIFcomplete dataset should describe its variables (schema:variableMeasured)." ;
                    sh:minCount 1 ;
                    sh:path schema1:variableMeasured ;
                    sh:severity sh:Warning ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/metadata-record-001> ;
            sh:resultMessage "A CDIFcomplete dataset should include provenance (prov:wasGeneratedBy)." ;
            sh:resultPath prov:wasGeneratedBy ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "A CDIFcomplete dataset should include provenance (prov:wasGeneratedBy)." ;
                    sh:minCount 1 ;
                    sh:path prov:wasGeneratedBy ;
                    sh:severity sh:Warning ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/metadata-record-001> ;
            sh:resultMessage "A CDIFcomplete dataset should have at least one distribution." ;
            sh:resultPath schema1:distribution ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "A CDIFcomplete dataset should have at least one distribution." ;
                    sh:minCount 1 ;
                    sh:path schema1:distribution ;
                    sh:severity sh:Warning ] ] .

